-- Academy training content. Adds rich per-unit fields (goal, content sections,
-- single photo task) plus a seeded default-curriculum catalog imported on
-- clinic sign-up. Questions are plain single-answer MCQs — the legacy
-- kind/explain annotations are out of scope for the training flow and the
-- exam auto-scores on correct_index only.

alter table academy_unit
    add column icon      text,
    add column goal      text,
    add column content   jsonb not null default '[]',
    add column photo_task text;

alter table academy_question
    add column display_order integer not null default 0;

alter table academy_step_submission
    add column reject_reason text;

create index idx_academy_submission_latest
    on academy_step_submission (clinic_id, employee_id, unit_id, submitted_at desc);

alter table academy_exam_attempt
    add column total_questions integer,
    add column correct_count integer;

create table academy_template_unit (
    id              uuid primary key default gen_random_uuid(),
    code            text not null unique,
    applies_to      academy_audience not null,
    icon            text,
    title           text not null,
    goal            text,
    content         jsonb not null default '[]',
    photo_task      text,
    display_order   integer not null unique
);

create table academy_template_question (
    id              uuid primary key default gen_random_uuid(),
    unit_id         uuid not null references academy_template_unit (id) on delete cascade,
    prompt          text not null,
    options         jsonb not null,
    correct_index   integer not null check (correct_index >= 0),
    display_order   integer not null default 0,
    unique (unit_id, display_order)
);

insert into academy_template_unit (code, applies_to, icon, title, goal, content, photo_task, display_order) values
('mindset', 'core', '🚀', 'عقلية النجاح والمبادرة',
 'تطلع من الوحدة دي وانت فاهم إزاي تتعلّم بسرعة، تبادر، وتكون قيمة حقيقية للفريق من أول يوم.',
 '[{"h":"القاعدة الذهبية","points":["اسأل بدل ما تخمّن — الغلط في التعلّم عادي، الغلط من غير سؤال لأ.","لو نسيت خطوة، ارجع للمنهج أو اسأل، متكمّلش على شكّ."]},{"h":"المبادرة بتفرق","points":["اللي بياخد خطوة قبل ما يتقاله بيتعلّم أسرع وبيكون قيمة للفريق.","لاحظ الناقص واعمله من غير انتظار (تراي مش مجهّز، مخزون قرب يخلص).","اكتب اللي بتتعلّمه — بيثبّت المعلومة."]},{"h":"روح الفريق","points":["العيادة فريق واحد: نجاح أي إجراء بيعتمد على الطبيب + الأسيستنت + الاستقبال.","احترام وقت المريض جزء من جودة الخدمة."]}]'::jsonb,
 null, 10),
('infection', 'core', '🧼', 'التعقيم ومكافحة العدوى (Infection Control)',
 'تطلع قادر تفرّق بين التنظيف والتطهير والتعقيم، وتعرف خطوات الأوتوكلاف وقواعد الأمان من غير ما تنسى حاجة.',
 '[{"h":"3 مستويات مهم تفرّق بينهم","points":["تنظيف (Cleaning): إزالة الأوساخ — مش بيقتل ميكروبات.","تطهير (Disinfection): بيقلّل أغلب الميكروبات (للأسطح).","تعقيم (Sterilization): بيقتل كل الميكروبات والأبواغ (للأدوات اللي بتلمس المريض)."]},{"h":"خطوات الأوتوكلاف بالترتيب","points":["1) تنظيف الأدوات من الدم والبقايا.","2) تغليف (Pouches) مع مؤشر تعقيم.","3) تحميل صح من غير تكدّس.","4) دورة التعقيم (حرارة + ضغط).","5) تخزين معقّم في مكان نظيف جاف."]},{"h":"الأمان والوقاية (PPE)","points":["جوانتي + ماسك + نظّارة قبل أي تعامل مع المريض.","غسل الأيدي قبل وبعد كل مريض حتى مع الجوانتي.","الأدوات الحادة (Sharps) في صندوقها المخصّص — ممنوع باليد.","تطهير سطح الكرسي والأسطح بين كل مريض والتاني."]}]'::jsonb,
 null, 20),
('instruments', 'core', '🪞', 'الأدوات (Instruments)',
 'تطلع تعرف كل أداة بالاسم والوظيفة والفرق بين أنواعها، وتجهّز التراي صح لأي إجراء من غير ما تنسى أو تغلط في الاختيار.',
 '[{"h":"أدوات الفحص (Diagnostic)","points":["ميرور (Mouth Mirror): 3 وظائف — الرؤية غير المباشرة، عكس الضوء على المنطقة، وإبعاد الخد/اللسان.","إكسبلورر / بروب (Explorer): سنّه حادة للكشف عن التسوّس والشروخ وحواف الحشو.","بيريو بروب (Periodontal Probe): مدرّجة بالمليمتر لقياس عمق جيب اللثة (مهمة في حالات اللثة).","تويزر (College Pliers): الإمساك بالقطن والمواد الصغيرة وتوصيلها لفم المريض."]},{"h":"الهاند بيس والبَرز (Handpieces & Burs)","points":["الهاند بيس التوربيني (High-speed / Airotor): سرعة عالية + رذاذ ماء، لقطع المينا وإزالة التسوّس الكبير.","الكونترا (Low-speed / Contra-angle): سرعة أقل وعزم أعلى، للتنظيف الدقيق والتلميع وإزالة التسوّس الناعم.","البَرز (Burs): ماسي (Diamond) للقطع والتحضير، كربيد (Carbide) للقطع الدقيق وإزالة الحشو القديم — بأشكال (round, fissure, flame).","قاعدة: كل إجراء وله البَر المناسب — معرفتها بتسرّع التحضير وتمنع الغلط."]},{"h":"أدوات الحشو (Restorative)","points":["حاملات الحشو (Composite/Amalgam carriers) ومضاغط (Condensers/Pluggers) لكبس المادة.","كارفرز (Carvers) ونحّاتات لتشكيل الحشو وضبط شكل السن.","سبتشولا (Spatula) لخلط المواد، والمصفوفة (Matrix band) + الإسفين (Wedge) لبناء جدار السن."]},{"h":"أدوات الجذور (Endodontic)","points":["كي-فايلز / إتش-فايلز (Files): تنظيف وتوسيع قنوات الجذر بمقاسات متدرّجة (#10، #15…).","سبريدر وبلجر: ضغط الجوتا بركا داخل القناة.","الريمر والـ Gates Glidden: توسيع مدخل القناة."]},{"h":"أدوات الخلع والجراحة (Surgical)","points":["فورسبس (Forceps): لكل سن شكل مختلف (علوي/سفلي، أمامي/خلفي) — الاختيار الصح أساسي.","إليفيتورز (Elevators / Luxators): فك ارتباط السن قبل الخلع.","أدوات الجراحة: مشرط (Blade)، ملقط نسيج، حامل إبرة (Needle holder)، مقص للخيوط."]},{"h":"تنظيم التراي (Tray Setup)","points":["رتّب الأدوات بترتيب الاستخدام الفعلي من اليمين لليسار.","كل إجراء وله تراي مختلف — إندو غير أوبريتيف غير إكستراكشن غير أورثو.","افصل الأدوات الحادة بوضوح، وراجع اكتمال التراي قبل دخول المريض."]}]'::jsonb,
 null, 30),
('materials', 'core', '🧪', 'المواد والخامات (Materials)',
 'تطلع تعرف كل مادة بتُستخدم في إيه، إزاي تتجهّز وتتتخلط صح، والأخطاء اللي بتفسد الإجراء.',
 '[{"h":"مواد الحشو التجميلي (Composite system)","points":["إيتش (Etchant / حمض الفوسفوريك 37٪): بيخشّن سطح المينا/العاج للالتصاق — يتحطّ ثم يتشطف ويتجفّف.","بوندينج (Bonding/Adhesive): الطبقة اللاصقة، تتحطّ وتتنفخ خفيف وتتصلّب بالـ Light cure.","كمبوزيت (Composite): بيتحطّ طبقات (Incremental) وكل طبقة تتصلّب لوحدها — بيتدرّج بالألوان (Shades) لمطابقة السن.","الـ Light cure: جهاز الضوء اللي بيصلّب المادة — مدة كافية لكل طبقة مهمة."]},{"h":"مواد بديلة وللأطفال","points":["جلاس أيونومر (Glass Ionomer): بيلتصق كيميائيًا ويطلّق فلورايد — مناسب للأطفال والحشوات المؤقتة وحالات معيّنة.","أمالجم (Amalgam): حشو فضي قديم، بيتخلط في كبسولة ويتكبس — أقل استخدامًا حاليًا.","RMGI: جلاس أيونومر معدّل بالريزن — يجمع مزايا الاتنين."]},{"h":"مواد علاج الجذور (Endo materials)","points":["هيبوكلورايت الصوديوم (NaOCl): محلول غسيل القنوات، بيذوّب البقايا ويعقّم — يتعامل معاه بحذر.","EDTA: بيزيل الطبقة اللطخية (Smear layer) وبيسهّل التنظيف.","جوتا بركا (Gutta-percha): أقماع مطاطية لحشو القناة بعد التنظيف.","سيلر (Sealer): معجون بيملا الفراغات بين الجوتا بركا وجدار القناة."]},{"h":"مواد الطبعات والتركيبات","points":["الألجينات (Alginate): طبعات أولية سريعة (دراسة/مؤقت) — بيتخلط بنسبة ماء:بودرة صح ووقت محدّد.","السيليكون (Addition/Condensation silicone): طبعات دقيقة للتركيبات النهائية.","أسمنت التركيب (Cement): مؤقت (Temp) للتيجان المؤقتة، ودائم (Permanent) للنهائية."]},{"h":"قواعد ذهبية في التعامل مع المواد","points":["نسبة الخلط والوقت (Working/Setting time) دقيقة — الغلط فيها بيفسد المادة.","تاريخ الصلاحية: المنتهي بيفقد خواصه حتى لو شكله سليم.","التخزين الصح (بعضها بيتحفظ في التلاجة) و FIFO (الأقرب انتهاءً يتستخدم الأول)."]}]'::jsonb,
 null, 40),
('chairside', 'core', '🤝', 'مساعدة الطبيب أثناء الإجراء (Chairside)',
 'تطلع تعرف تناول الطبيب صح، تتوقّع الخطوة الجاية، وتحافظ على مجال رؤية نظيف وآمن.',
 '[{"h":"مبدأ الـ Four-handed","points":["تناول الطبيب الأداة الصح في الوقت الصح من غير ما يبص بعيد عن الفم.","المناولة تكون من تحت ذقن المريض (Transfer zone) وبشكل آمن للأدوات الحادة.","امسك الأداة من الطرف اللي مش هيستخدمه الطبيب عشان يستلمها جاهزة."]},{"h":"السكشن والرؤية","points":["نوعان: الـ High-volume (HVE) للشفط القوي، واللعابي (Saliva ejector) الخفيف.","ضع طرف السكشن قريب من منطقة العمل من غير ما يعيق رؤية الطبيب.","سكشن مستمر + توجيه الإضاءة = مجال نظيف واضح."]},{"h":"توقّع الخطوة الجاية","points":["لو فاهم تسلسل الإجراء بتجهّز الأداة/المادة قبل ما الطبيب يطلبها.","ده بيوفّر وقت وبيدّي إحساس إن التحضير سريع ومريح للطبيب والمريض."]},{"h":"إدارة المريض أثناء الإجراء","points":["طمئن المريض بكلمة بسيطة وراقب علامات الانزعاج.","جهّز القطن والشاش وكوب المضمضة في متناول إيدك."]}]'::jsonb,
 null, 50),
('procedures', 'core', '🦷', 'تسلسل الإجراءات + دور الأسيستنت (Procedures)',
 'تطلع حافظ تسلسل كل إجراء أساسي، وعارف بالظبط دورك في كل خطوة والأداة/المادة اللي تجهّزها.',
 '[{"h":"أوبريتيف / حشو (Operative)","points":["1) تخدير → دورك: تجهّز السرنجة والكبسولة والجل السطحي.","2) عزل (Rubber dam/قطن) + سكشن → دورك: تحافظ على جفاف ورؤية المنطقة.","3) تحضير الكافيتي بالبَر → دورك: سكشن مستمر وتوجيه الإضاءة.","4) إيتش → شطف → تجفيف → بوندينج → تصليب → دورك: تناول كل مادة في وقتها وتشغّل الـ Light cure.","5) كمبوزيت طبقات + تصليب → ضبط العضّة بورق الـ Articulating → تلميع."]},{"h":"إندو / علاج جذور (Endodontics)","points":["1) تخدير + عزل (Rubber dam ضروري).","2) فتح الحجرة (Access) بالبَر.","3) تنظيف وتوسيع القنوات بالفايلز + غسيل بالـ NaOCl → دورك: تجهّز الفايلز بالترتيب وتدير الغسيل والشفط.","4) تجفيف بالـ Paper points.","5) حشو القنوات (جوتا بركا + سيلر) → دورك: تجهّز الأقماع والسيلر.","6) حشو مؤقت أو دائم + أشعة للتأكد."]},{"h":"إكستراكشن / خلع (Extraction)","points":["1) تخدير والتأكد من تنميله.","2) فك الرباط حوالين السن بالإليفيتور.","3) الخلع بالفورسبس المناسب للسن.","4) دورك: سكشن، تجهيز الشاش، ومتابعة المريض.","5) شاش للعض + تعليمات ما بعد الخلع (ثلج، تجنّب المضمضة القوية، الأدوية)."]},{"h":"كراون / تركيبات (Crown & Bridge)","points":["1) تخدير وتحضير السن بالبَر.","2) إزاحة اللثة (Retraction cord) → أخذ الطبعة (سيليكون).","3) تحديد اللون (Shade).","4) تركيب تاج مؤقت بأسمنت مؤقت لحين النهائي.","5) جلسة تانية: تجربة وتثبيت النهائي بالأسمنت الدائم."]},{"h":"سكيلينج / تنظيف (Scaling)","points":["إزالة الجير بالسكيلر فوق صوتي (Ultrasonic) + سكشن قوي.","تلميع بالـ Prophy paste والكوب المطاطي.","نصائح العناية المنزلية للمريض."]},{"h":"قاعدة الأسيستنت الذكي","points":["لو فاهم التسلسل، بتجهّز الخطوة الجاية قبل ما الطبيب يطلبها.","ربط كل خطوة بأداتها ومادتها = تحضير سريع وإجراء سلس."]}]'::jsonb,
 null, 60),
('patient', 'core', '💬', 'التعامل مع المريض',
 'تطلع عارف تطمّن المريض، تتعامل مع الأطفال، وتحافظ على سرّية معلوماته.',
 '[{"h":"تجربة المريض","points":["استقباله باسمه وابتسامة بيقلّل توتره.","شرح بسيط لكل خطوة بيطمّنه — من غير تفاصيل مخيفة."]},{"h":"التعامل مع الطفل","points":["أسلوب Tell-Show-Do: تقوله، تورّيه، تعمل — بصبر.","التشتيت الإيجابي والمكافأة بعد الجلسة."]},{"h":"السرّية","points":["معلومات المريض سرّية — ما تتقالش لحد ولا تتنشر.","الخصوصية جزء من ثقة المريض في العيادة."]}]'::jsonb,
 null, 70),
('asstadv', 'assistant', '🧰', 'الأسيستنت — تجهيز وإتقان متقدّم',
 'تطلع تعرف تجهّز الغرفة والمخزون وشنطة التقويم بإتقان وتنسّق مع المعمل.',
 '[{"h":"تجهيز الغرفة","points":["جهّز الغرفة والتراي قبل كل مريض حسب نوع الإجراء.","عقّم وطهّر الأسطح بين كل مريض والتاني."]},{"h":"المخزون والتنسيق","points":["تابع المخزون واطلب الناقص قبل ما يخلص (مش بعد).","نسّق مع المعمل الخارجي للتركيبات في وقتها."]},{"h":"شنطة التقويم (Ortho Kit)","points":["جهّزها كاملة: بلايرز (وينجارت/ماتيو)، كَترز، براكتس، أسلاك، لايجيتشرز، مواد بوندينج.","راجع القائمة قبل جلسة التقويم عشان ما ينقصش حاجة."]}]'::jsonb,
 'صوّر تراي مجهّز بالكامل لكل أدوات الفحص مرتبة بالترتيب الصح', 80),
('frontdesk', 'receptionist', '🗓️', 'الاستقبال — التنظيم والتعامل',
 'تطلع تعرف تدير المواعيد والتليفون باحتراف، تقلّل الغياب، وتكبّر سمعة العيادة.',
 '[{"h":"المواعيد والتواصل","points":["تنظيم الجدول لمنع التزاحم أو الفراغات.","الرد على التليفون والواتساب بسرعة (خلال دقائق) واحتراف.","تأكيد مواعيد بكرة بيقلّل الغياب (No-shows)."]},{"h":"النمو والسمعة","points":["تسجيل مصدر كل مريض جديد (إعلان/ترشيح/جوجل) للتسويق.","طلب تقييم جوجل من المريض الراضي بيكبّر العيادة.","التعامل مع الشكاوى بهدوء وتصعيدها للمسؤول."]},{"h":"الانطباع الأول","points":["نظافة وترتيب الاستقبال = انطباع أول عن العيادة كلها."]}]'::jsonb,
 'صوّر شاشة جدول مواعيد اليوم والترتيب النهائي', 90);

insert into academy_template_question (unit_id, prompt, options, correct_index, display_order)
select u.id, q.prompt, q.options::jsonb, q.correct_index, q.display_order
from academy_template_unit u
cross join lateral (values
 ('لو مش متأكد من خطوة في إجراء، الأصحّ:', '["تخمّن وتكمّل بسرعة","تسأل المسؤول قبل ما تكمّل","تسيبها وتعدّي"]'::jsonb, 1, 1),
 ('دخلت الغرفة لقيت التراي مش مجهّز والطبيب جاي بعد دقيقتين والمريض قاعد. تعمل إيه؟', '["تستنى الطبيب يقولك","تجهّز التراي فورًا حسب نوع الإجراء","تقول للمريض يستنى بره"]'::jsonb, 1, 2),
 ('أسيستنت قال: «أنا بعمل اللي يتقالي بالظبط وبس، الباقي مش شغلي.» الغلط فين؟', '["مفيش غلط، ده صح","غياب المبادرة — القيمة الحقيقية في إنه يلاحظ ويبادر","المفروض يرفض اللي يتقاله"]'::jsonb, 1, 3)
) as q(prompt, options, correct_index, display_order)
where u.code = 'mindset';

insert into academy_template_question (unit_id, prompt, options, correct_index, display_order)
select u.id, q.prompt, q.options::jsonb, q.correct_index, q.display_order
from academy_template_unit u
cross join lateral (values
 ('الأداة اللي بتلمس داخل فم المريض لازم تتعرّض لـ:', '["تنظيف بس","تطهير بس","تعقيم كامل (Sterilization)"]'::jsonb, 2, 1),
 ('مؤشر التعقيم (Indicator) اللي بيغيّر لونه بيأكّد:', '["نظافة إيد الأسيستنت","إن دورة التعقيم تمّت فعلًا","نوع الأداة"]'::jsonb, 1, 2),
 ('خلّصت إجراء وفيه إبرة تخدير مستعملة على التراي. تتصرف إزاي؟', '["ترميها في الزبالة العادية","تحطها في صندوق الـ Sharps","تسيبها على التراي للمريض اللي بعده"]'::jsonb, 1, 3),
 ('أسيستنت غسل إيده، لبس جوانتي، عمل الإجراء، وعدّى للمريض اللي بعده بنفس الجوانتي من غير ما يغسل. الغلط فين؟', '["مفيش غلط طالما لابس جوانتي","لازم يغيّر الجوانتي ويغسل إيده بين كل مريض","الغلط إنه غسل إيده من الأول"]'::jsonb, 1, 4)
) as q(prompt, options, correct_index, display_order)
where u.code = 'infection';

insert into academy_template_question (unit_id, prompt, options, correct_index, display_order)
select u.id, q.prompt, q.options::jsonb, q.correct_index, q.display_order
